import{_ as a,o as t,c as d,ag as i}from"./chunks/framework.Dh3ZG9qC.js";const u=JSON.parse('{"title":"连接设备与虚拟屏","description":"","frontmatter":{},"headers":[],"relativePath":"guide/devices.md","filePath":"guide/devices.md","lastUpdated":null}'),r={name:"guide/devices.md"};function s(o,e,l,n,h,c){return t(),d("div",null,[...e[0]||(e[0]=[i('<h1 id="连接设备与虚拟屏" tabindex="-1">连接设备与虚拟屏 <a class="header-anchor" href="#连接设备与虚拟屏" aria-label="Permalink to &quot;连接设备与虚拟屏&quot;">​</a></h1><p>Gamer 统一通过 ADB 连接设备。真机、模拟器都填写完整 ADB 地址，不需要选择设备类别。</p><h2 id="检查-adb" tabindex="-1">检查 ADB <a class="header-anchor" href="#检查-adb" aria-label="Permalink to &quot;检查 ADB&quot;">​</a></h2><p>在服务端电脑执行：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">adb devices </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">l</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>只有状态为 <code>device</code> 的设备才已准备好。<code>unauthorized</code> 表示需要在 Android 屏幕上确认调试授权；<code>offline</code> 表示当前 ADB 链路不可用。</p><table tabindex="0"><thead><tr><th>连接方式</th><th>在 Gamer 中填写的地址</th></tr></thead><tbody><tr><td>USB</td><td>列表中完整的 serial</td></tr><tr><td>模拟器已注册到 ADB</td><td>如 <code>emulator-5554</code>，以列表为准</td></tr><tr><td>网络端点</td><td>如 <code>192.168.1.20:5555</code>，服务端执行 <code>adb connect</code></td></tr><tr><td>Android 无线调试</td><td>完成配对后扫描，保留完整 mDNS serial 或连接地址</td></tr></tbody></table><p>设备型号和显示名称不能代替 serial。网络端口由设备或模拟器决定，示例端口不保证适用于你的环境。</p><h2 id="工作台操作" tabindex="-1">工作台操作 <a class="header-anchor" href="#工作台操作" aria-label="Permalink to &quot;工作台操作&quot;">​</a></h2><ol><li>在设备工具栏刷新扫描，或通过设备菜单新增设备。</li><li>选中设备，进入设备设置核对 ADB 地址和屏幕参数。</li><li>建立投屏连接。</li><li>读取应用列表，选择运行目标，再点击启动应用。</li></ol><p>连接投屏不会自动启动应用。设备设置里的投屏参数与工具栏的应用选择分别保存；改名称或应用通常不需要重建投屏会话。</p><h2 id="镜像与虚拟屏" tabindex="-1">镜像与虚拟屏 <a class="header-anchor" href="#镜像与虚拟屏" aria-label="Permalink to &quot;镜像与虚拟屏&quot;">​</a></h2><p><strong>镜像主屏</strong>用于查看和控制设备当前物理屏幕。<strong>虚拟屏</strong>创建独立显示，可设置宽高、DPI 和帧率，例如 1920×1080。</p><p>虚拟屏需要 Android 系统和应用支持。失败时会显示错误，不会静默切到主屏。游戏可能改变实际分辨率或方向；取坐标时以当前投屏画面为准。</p><p>投屏参数修改可能触发会话重建。脚本运行期间，新的会话参数可能推迟到下次连接生效，建议停止运行后再调整。</p><h2 id="多页面和后台运行" tabindex="-1">多页面和后台运行 <a class="header-anchor" href="#多页面和后台运行" aria-label="Permalink to &quot;多页面和后台运行&quot;">​</a></h2><p>一个设备同时只有一个浏览器观看连接。另一页面请求接管时需要确认；被接管的页面停止自动重连，避免反复争抢。</p><p>浏览器断开与设备会话停止不同。脚本和任务在服务端继续运行；空闲低功耗由服务端依据观看者和运行状态管理。</p><h2 id="跨电脑访问" tabindex="-1">跨电脑访问 <a class="header-anchor" href="#跨电脑访问" aria-label="Permalink to &quot;跨电脑访问&quot;">​</a></h2><p>默认 WebRTC 采用 host candidate，适合同机或局域网。跨 NAT 需要配置外部地址和 UDP 映射，详见<a href="./../reference/configuration.html#webrtc-网络">配置参考</a>。HTTP 页面可访问但视频不出现时，先检查 UDP 路径。</p>',20)])])}const b=a(r,[["render",s]]);export{u as __pageData,b as default};
